sp_widget.client_script:
api.controller = function($interval, $scope) {
  /* widget controller */
  var c = this;

  c.initCountdown = function() {
    var eventDate = new Date("2025-09-01T09:00:00"); // Replace with actual event start date/time
    var now = new Date();
    var timeLeft = eventDate - now;

    var el = document.getElementById("countdown");
    if (!el) return;

    if (timeLeft <= 0) {
      el.innerText = "🚨 The hackathon has started!";
      return;
    }

    var days = Math.floor(timeLeft / (1000 * 60 * 60 * 24));
    var hours = Math.floor((timeLeft / (1000 * 60 * 60)) % 24);
    var minutes = Math.floor((timeLeft / (1000 * 60)) % 60);
    var seconds = Math.floor((timeLeft / 1000) % 60);

    el.innerText = days + "d " + hours + "h " + minutes + "m " + seconds + "s";
  };

  // Run countdown once and set interval
  c.initCountdown();
  c.interval = $interval(c.initCountdown, 1000);

  // Clear interval on destroy
  $scope.$on('$destroy', function() {
    $interval.cancel(c.interval);
  });
};

sp_widget.css:
.card {
  border-radius: 12px;
  transition: transform 0.2s ease;
}
.card:hover {
  transform: scale(1.02);
}
.card-title {
  font-weight: bold;
  margin-bottom: 0.5rem;
}

